function New-TestPcmWav([string]$Path, [int]$Channels, [int]$SampleRate, [int]$DurationSeconds) {
  $bits = 16
  $byteRate = $Channels * $SampleRate * ($bits / 8)
  $dataLength = $byteRate * $DurationSeconds
  $stream = [IO.File]::Open($Path, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write)
