  $manifestPath = Join-Path $root 'existing-manifest.json'
  [IO.File]::WriteAllText($manifestPath, 'user manifest', [Text.UTF8Encoding]::new($false))
  $blockedOutput = Join-Path $root 'must-not-exist.wav'
  $preflightFailed = $false
