const childProcess = require('child_process');
const fs = require('fs');
const path = require('path');

const media = require('./health-demo-media.js');

const PROJECT_ROOT = path.resolve(__dirname, '..');
const OUTPUT_DIRECTORY = path.join(PROJECT_ROOT, 'output', 'video', 'official-health-demo-v2');
const FFMPEG_PATH = path.join(
  PROJECT_ROOT,
  'output',
  'video',
  '.deps',
  'imageio_ffmpeg',
  'binaries',
  'ffmpeg-win-x86_64-v7.1.exe',
);
const CAPTURE_MANIFEST_PATH = path.join(OUTPUT_DIRECTORY, 'capture-manifest.json');
const MASTER_FILENAME = '腕上节律-官方模拟器健康数据演示-母版.mp4';
const FINAL_FILENAME = '腕上节律-官方模拟器健康数据演示-成片.mp4';
const NARRATION_FILENAME = '腕上节律-官方模拟器健康数据演示-旁白.wav';
const SUBTITLE_FILENAME = '腕上节律-官方模拟器健康数据演示-字幕.srt';
const FPS = 10;
const TARGET_DURATION_SECONDS = 60;

function resolveOutputPath(filePath) {
  const resolvedPath = path.resolve(filePath);
  const relativePath = path.relative(OUTPUT_DIRECTORY, resolvedPath);
  if (!relativePath || relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
    throw new Error(`Unsafe composition output path outside ${OUTPUT_DIRECTORY}: ${resolvedPath}`);
  }
  return resolvedPath;
}

function resolveFrameDirectory(frameDirectory) {
  const resolvedDirectory = path.resolve(frameDirectory);
  const relativePath = path.relative(OUTPUT_DIRECTORY, resolvedDirectory);
  if (!relativePath || relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
    throw new Error(`Unsafe raw frame directory outside ${OUTPUT_DIRECTORY}: ${resolvedDirectory}`);
  }
  return resolvedDirectory;
}

function locateFfmpeg(ffmpegPath = FFMPEG_PATH) {
  const resolvedPath = path.resolve(ffmpegPath);
  if (!fs.existsSync(resolvedPath) || !fs.statSync(resolvedPath).isFile()) {
    throw new Error(`Bundled FFmpeg is missing: ${resolvedPath}. Expected output/video/.deps/imageio_ffmpeg/binaries/ffmpeg-win-x86_64-v7.1.exe`);
  }
  return resolvedPath;
}

function framePattern(frameDirectory) {
  return path.join(resolveFrameDirectory(frameDirectory), 'frame-%04d.png');
}

function trimFilterGraph(editSegments = media.EDIT_SEGMENTS) {
  const trims = editSegments.map(([start, end], index) => (
    `[0:v]trim=start=${start}:end=${end},setpts=PTS-STARTPTS[v${index}]`
  ));
  const inputLabels = editSegments.map((_, index) => `[v${index}]`).join('');
  return [
    ...trims,
    `${inputLabels}concat=n=${editSegments.length}:v=1:a=0[cut]`,
    '[cut]scale=932:932:flags=lanczos,setsar=1,format=yuv420p[video]',
  ].join(';');
}

function buildIntermediateArguments({ frameDirectory, intermediatePath, fps = FPS }) {
  return [
    '-hide_banner', '-loglevel', 'error', '-n',
    '-framerate', String(fps), '-start_number', '1', '-i', framePattern(frameDirectory),
    '-map', '0:v:0', '-an', '-c:v', 'ffv1', '-level', '3', '-g', '1', '-pix_fmt', 'rgb24',
    resolveOutputPath(intermediatePath),
  ];
}

function buildMasterArguments({ intermediatePath, masterPath, editSegments = media.EDIT_SEGMENTS }) {
  return [
    '-hide_banner', '-loglevel', 'error', '-n',
    '-i', path.resolve(intermediatePath),
    '-filter_complex', trimFilterGraph(editSegments),
    '-map', '[video]', '-an', '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-movflags', '+faststart',
    resolveOutputPath(masterPath),
  ];
}

function buildFinalArguments({ masterPath, narrationPath, subtitlePath, finalPath }) {
  return [
    '-hide_banner', '-loglevel', 'error', '-n',
    '-i', path.resolve(masterPath), '-i', path.resolve(narrationPath), '-i', path.resolve(subtitlePath),
    '-filter_complex', '[1:a]apad=whole_dur=60,atrim=duration=60[audio]',
    '-map', '0:v:0', '-map', '[audio]', '-map', '2:0',
    '-c:v', 'copy', '-c:a', 'aac', '-c:s', 'mov_text',
    '-metadata:s:s:0', 'language=zho', '-t', String(TARGET_DURATION_SECONDS), '-movflags', '+faststart',
    resolveOutputPath(finalPath),
  ];
}

function validateNarrationWav(narrationPath) {
  const resolvedPath = path.resolve(narrationPath);
  if (!fs.existsSync(resolvedPath)) throw new Error(`Narration WAV is missing: ${resolvedPath}`);
  const metadata = media.readPcmWavMetadata(fs.readFileSync(resolvedPath));
  if (metadata.durationSeconds > TARGET_DURATION_SECONDS) {
    throw new Error(`Narration WAV exceeds 60 seconds; regenerate the cue-aligned narration instead of trimming speech: ${resolvedPath}`);
  }
  return metadata;
}

function loadCaptureManifest(manifestPath = CAPTURE_MANIFEST_PATH) {
  const resolvedPath = path.resolve(manifestPath);
  if (!fs.existsSync(resolvedPath)) throw new Error(`Capture manifest is missing: ${resolvedPath}`);
  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(resolvedPath, 'utf8'));
  } catch (error) {
    throw new Error(`Capture manifest is not valid JSON: ${resolvedPath} (${error.message})`);
  }
  if (!manifest || !manifest.frameDirectory || manifest.fps !== FPS || !Number.isInteger(manifest.frames)) {
    throw new Error(`Capture manifest is missing the required frameDirectory, ${FPS} fps, or frame count: ${resolvedPath}`);
  }
  return { ...manifest, frameDirectory: resolveFrameDirectory(manifest.frameDirectory) };
}

function validateFrameSequence(frameDirectory, frames) {
  if (!fs.existsSync(frameDirectory) || !fs.statSync(frameDirectory).isDirectory()) {
    throw new Error(`Raw frame directory is missing: ${frameDirectory}`);
  }
  for (let index = 1; index <= frames; index += 1) {
    const framePath = path.join(frameDirectory, `frame-${String(index).padStart(4, '0')}.png`);
    if (!fs.existsSync(framePath) || !fs.statSync(framePath).size) {
      throw new Error(`Missing or empty captured frame ${index}: ${framePath}`);
    }
  }
}

function runFfmpeg(ffmpegPath, argumentsList, spawnSync = childProcess.spawnSync) {
  const result = spawnSync(ffmpegPath, argumentsList, { encoding: 'utf8', shell: false });
  if (result.error) throw new Error(`FFmpeg could not start: ${result.error.message}`);
  if (result.status !== 0) {
    const details = [result.stderr, result.stdout].filter(Boolean).join('\n').trim();
    throw new Error(`FFmpeg failed with exit status ${result.status}${details ? `: ${details}` : ''}`);
  }
  return result;
}

function assertAbsent(filePath, label) {
  if (fs.existsSync(filePath)) throw new Error(`${label} already exists and will not be overwritten: ${filePath}`);
}

function compose(options = {}) {
  const manifest = loadCaptureManifest(options.manifestPath);
  const frameDirectory = manifest.frameDirectory;
  validateFrameSequence(frameDirectory, manifest.frames);

  const ffmpegPath = locateFfmpeg(options.ffmpegPath);
  const masterPath = resolveOutputPath(options.masterPath || path.join(OUTPUT_DIRECTORY, MASTER_FILENAME));
  const finalPath = resolveOutputPath(options.finalPath || path.join(OUTPUT_DIRECTORY, FINAL_FILENAME));
  const narrationPath = path.resolve(options.narrationPath || path.join(OUTPUT_DIRECTORY, NARRATION_FILENAME));
  const subtitlePath = path.resolve(options.subtitlePath || path.join(OUTPUT_DIRECTORY, SUBTITLE_FILENAME));
  const intermediatePath = resolveOutputPath(options.intermediatePath || path.join(OUTPUT_DIRECTORY, `compose-intermediate-${process.pid}.mkv`));

  assertAbsent(masterPath, 'Silent master');
  assertAbsent(finalPath, 'Final video');
  assertAbsent(intermediatePath, 'Temporary intermediate');
  validateNarrationWav(narrationPath);
  if (!fs.existsSync(subtitlePath)) throw new Error(`UTF-8 SRT subtitle file is missing: ${subtitlePath}`);

  try {
    runFfmpeg(ffmpegPath, buildIntermediateArguments({ frameDirectory, intermediatePath }), options.spawnSync);
    runFfmpeg(ffmpegPath, buildMasterArguments({ intermediatePath, masterPath }), options.spawnSync);
    runFfmpeg(ffmpegPath, buildFinalArguments({ masterPath, narrationPath, subtitlePath, finalPath }), options.spawnSync);
  } finally {
    if (fs.existsSync(intermediatePath)) fs.rmSync(intermediatePath);
  }
  return { masterPath, finalPath };
}

if (require.main === module) {
  try {
    console.log(JSON.stringify(compose(), null, 2));
  } catch (error) {
    console.error(error.message || error);
    process.exitCode = 1;
  }
}

module.exports = {
  PROJECT_ROOT,
  OUTPUT_DIRECTORY,
  FFMPEG_PATH,
  CAPTURE_MANIFEST_PATH,
  MASTER_FILENAME,
  FINAL_FILENAME,
  FPS,
  TARGET_DURATION_SECONDS,
  resolveOutputPath,
  resolveFrameDirectory,
  locateFfmpeg,
  framePattern,
  trimFilterGraph,
  buildIntermediateArguments,
  buildMasterArguments,
  buildFinalArguments,
  validateNarrationWav,
  loadCaptureManifest,
  validateFrameSequence,
  runFfmpeg,
  compose,
};

